(function() {
    'use strict';

    var ROUNDS = [
        {
            title: 'Round 1: Ad Creative Optimization',
            titleEs: 'Ronda 1: Optimizacion de Creatividades Publicitarias',
            briefing: 'VERADA has developed five candidate creative executions for the MERIDIAN launch campaign. Traditional copy-testing scores differ significantly from the EEG data in three of the five executions. Select the primary creative execution based on your interpretation of the neuromarketing data versus traditional survey results.',
            briefingEs: 'VERADA ha desarrollado cinco creatividades candidatas para la campana de lanzamiento de MERIDIAN. Las puntuaciones de copy-testing tradicional difieren significativamente de los datos de EEG en tres de las cinco ejecuciones. Selecciona la creatividad principal basandote en tu interpretacion de los datos de neuromarketing versus los resultados de encuestas tradicionales.',
            dataHtml: '<table><tr><th>Creative</th><th>Concept</th><th>Survey Liking (1-10)</th><th>EEG AAI (-1 to +1)</th><th>EEG EI (0-100)</th><th>GSR SAS (0-100)</th></tr><tr><td><strong>C-1</strong></td><td>The Science of You (data-heavy explainer)</td><td>6.2</td><td class="mindmarket-sim-positive">+0.31</td><td class="mindmarket-sim-positive">78</td><td>42</td></tr><tr><td><strong>C-2</strong></td><td>Morning. Owned. (aspirational lifestyle)</td><td class="mindmarket-sim-highlight">7.8</td><td class="mindmarket-sim-negative">-0.12</td><td>52</td><td class="mindmarket-sim-warning">71</td></tr><tr><td><strong>C-3</strong></td><td>Clean Inside Out (nature, emotional arc)</td><td class="mindmarket-sim-highlight">8.1</td><td class="mindmarket-sim-positive">+0.48</td><td class="mindmarket-sim-positive">71</td><td>58</td></tr><tr><td><strong>C-4</strong></td><td>Athletes and Others (testimonials)</td><td>7.1</td><td>+0.22</td><td class="mindmarket-sim-positive">83</td><td>65</td></tr><tr><td><strong>C-5</strong></td><td>MERIDIAN: The Edge (minimal, provocative)</td><td>5.4</td><td class="mindmarket-sim-positive">+0.38</td><td>44</td><td class="mindmarket-sim-warning">81</td></tr></table><p style="margin-top:12px;font-size:0.82rem;color:#9999bb;"><strong>Key:</strong> AAI = Approach-Avoidance Index (positive = approach motivation). EI = Engagement Index. SAS = Sustained Arousal Score. Note: GSR arousal is valence-neutral &mdash; high arousal can mean excitement OR anxiety. EEG sample N=38.</p>'
        },
        {
            title: 'Round 2: Pricing Frame Selection',
            titleEs: 'Ronda 2: Seleccion del Marco de Precio',
            briefing: 'MERIDIAN will launch at $6.49 per bottle. The question is not which price to charge but how to frame and present that price to minimize loss aversion, maximize perceived value, and set favorable reference price anchors. Select one pricing frame for the primary retail shelf label and DTC product page.',
            briefingEs: 'MERIDIAN se lanzara a $6.49 por botella. La pregunta no es que precio cobrar sino como enmarcar y presentar ese precio para minimizar la aversion a la perdida, maximizar el valor percibido y establecer anclajes de precio favorables. Selecciona un marco de precio para la etiqueta del estante y la pagina DTC.',
            dataHtml: '<table><tr><th>Frame</th><th>Description</th><th>Survey WTP Uplift</th><th>GSR Peak</th><th>IAT Value</th></tr><tr><td><strong>P-1</strong></td><td>Bare Price: $6.49 per bottle</td><td>Baseline</td><td class="mindmarket-sim-negative">High</td><td>Neutral</td></tr><tr><td><strong>P-2</strong></td><td>Per-Day Anchor: Less than your daily coffee</td><td>+12%</td><td>Moderate</td><td>Positive</td></tr><tr><td><strong>P-3</strong></td><td>Cost-Per-Benefit: $6.49 = 72h focus support</td><td>+18%</td><td>Low-Mod</td><td class="mindmarket-sim-positive">Strong +</td></tr><tr><td><strong>P-4</strong></td><td>Subscription Default: $5.19/bottle subscribe</td><td class="mindmarket-sim-positive">+22%</td><td>Low</td><td class="mindmarket-sim-positive">Positive +</td></tr><tr><td><strong>P-5</strong></td><td>Social Proof: Joined by 120,000 seekers</td><td>+9%</td><td>Moderate</td><td class="mindmarket-sim-positive">Strong self-concept</td></tr><tr><td><strong>P-6</strong></td><td>Premium Anchor: Others charge $9+, MERIDIAN $6.49</td><td class="mindmarket-sim-highlight">+24%</td><td class="mindmarket-sim-positive">Low</td><td class="mindmarket-sim-positive">Very positive</td></tr><tr><td><strong>P-7</strong></td><td>Scarcity: Founding Member Pricing, limited window</td><td>+16%</td><td class="mindmarket-sim-negative">High</td><td class="mindmarket-sim-warning">Mod (skepticism)</td></tr><tr><td><strong>P-8</strong></td><td>Bundle: 3-pack $18.49, save and never run out</td><td>+19%</td><td>Moderate</td><td>Positive</td></tr><tr><td><strong>P-9</strong></td><td>Charitable: $0.50 supports clean water access</td><td>+7%</td><td>Moderate</td><td class="mindmarket-sim-positive">Strong ethical</td></tr></table><p style="margin-top:12px;font-size:0.82rem;color:#9999bb;"><strong>Key:</strong> WTP = Willingness-to-Pay uplift vs. control. GSR Peak at price reveal moment. IAT = Implicit association with value/trust. Note: High GSR at price reveal indicates loss aversion activation. Low GSR = loss aversion suppressed.</p>'
        },
        {
            title: 'Round 3: Store Layout & Digital UX',
            titleEs: 'Ronda 3: Distribucion en Tienda y UX Digital',
            briefing: 'Select a retail shelf configuration and a digital landing page variant based on eye-tracking data. Then respond to the Consumer Neuroscience Ethics Panel challenge on your previous decisions.',
            briefingEs: 'Selecciona una configuracion de estante y una variante de pagina de destino digital basandote en datos de eye-tracking. Luego responde al desafio del Panel de Etica en Neurociencia del Consumidor sobre tus decisiones anteriores.',
            dataHtml: '<table><tr><th>Config</th><th>First Fixation</th><th>Brand Dwell (s)</th><th>Price Dwell (s)</th><th>Gaze Path Complexity</th></tr><tr><td><strong>Shelf A</strong></td><td>Price label</td><td>1.2</td><td class="mindmarket-sim-negative">2.8</td><td>Low (linear)</td></tr><tr><td><strong>Shelf B</strong></td><td>Brand logo</td><td class="mindmarket-sim-positive">2.4</td><td>1.5</td><td>Medium</td></tr><tr><td><strong>Shelf C</strong></td><td>Hero ingredient</td><td>1.8</td><td>1.1</td><td class="mindmarket-sim-warning">High (backtracking)</td></tr></table><br><table><tr><th>UX Variant</th><th>Info Density</th><th>Social Proof</th><th>CTA Fixation %</th><th>Gaze Backtracking</th></tr><tr><td><strong>V-1</strong></td><td>High</td><td>Above fold</td><td class="mindmarket-sim-warning">28%</td><td class="mindmarket-sim-negative">High (confusion)</td></tr><tr><td><strong>V-2</strong></td><td>Low</td><td>Above fold</td><td class="mindmarket-sim-positive">62%</td><td>Low (clear path)</td></tr><tr><td><strong>V-3</strong></td><td>High</td><td>Below fold</td><td>41%</td><td>Moderate</td></tr><tr><td><strong>V-4</strong></td><td>Low</td><td>Below fold</td><td>55%</td><td>Low</td></tr></table><p style="margin-top:12px;font-size:0.82rem;color:#9999bb;"><strong>Key:</strong> First Fixation = what captures attention first. Dwell = time spent looking. Gaze Path Complexity = how chaotic the scan pattern is (high = confusion). Note: High fixation density does NOT mean positive engagement. Eye-tracking shelf study N=52; digital study N=41. Lab conditions may not reflect in-store visual clutter.</p>'
        },
        {
            title: 'Round 4: Loyalty Program Architecture',
            titleEs: 'Ronda 4: Arquitectura del Programa de Lealtad',
            briefing: 'Design the MERIDIAN loyalty program reward schedule informed by neuroscience of reward. Then identify which neuro data point across all previous rounds you believe you may have over-weighted in your decisions. Early soft-launch data suggests one neuro-driven decision has underperformed expectations.',
            briefingEs: 'Disena el programa de lealtad MERIDIAN basandote en la neurociencia de la recompensa. Luego identifica que dato neuro de las rondas anteriores crees haber sobreponderado. Los datos preliminares del soft-launch sugieren que una decision basada en neuro ha tenido un rendimiento inferior.',
            dataHtml: '<table><tr><th>Schedule</th><th>Structure</th><th>Neural Mechanism</th><th>Commercial Implication</th></tr><tr><td><strong>Fixed Ratio</strong></td><td>Reward after every N purchases</td><td>Consummatory dopamine; habituates rapidly</td><td>High initial uptake, rapid engagement decay</td></tr><tr><td><strong>Variable Ratio</strong></td><td>Reward after random N purchases</td><td>Tonic dopamine + anticipatory spikes; resists habituation</td><td>Lower initial uptake but higher long-run engagement</td></tr><tr><td><strong>Progressive Status</strong></td><td>Tiered with visible milestones</td><td>Social comparison + status circuitry (striatum)</td><td>High for status-motivated; alienating for others</td></tr><tr><td><strong>Social-Achievement</strong></td><td>Community milestones, group goals</td><td>Oxytocin-mediated social bonding + dopamine</td><td>Strong for community-driven; low for individualists</td></tr></table><p style="margin-top:12px;font-size:0.82rem;color:#9999bb;"><strong>Key:</strong> Variable ratio schedules produce the most sustained neural engagement through anticipatory dopamine elevation. Fixed ratio schedules habituate fastest. Consider MERIDIAN target segment (urban high-performers aged 28-45) when evaluating schedule fit.</p>'
        }
    ];

    var ANSWER_KEY = {
        r1: { 'C-3': 5, 'C-1': 4, 'C-5': 3, 'C-4': 2, 'C-2': 1 },
        r2: { 'P-6': 5, 'P-4': 4.5, 'P-3': 4, 'P-8': 3.5, 'P-5': 3, 'P-2': 2.5, 'P-9': 2, 'P-7': 1.5, 'P-1': 1 },
        r3shelf: { 'B': 5, 'A': 2, 'C': 3 },
        r3ux: { 'V-2': 5, 'V-4': 4, 'V-3': 3, 'V-1': 1 },
        r3ethics: { 'principled': 2, 'generic': 1, 'commercial': 0 },
        r4schedule: { 'variable': 5, 'social': 4, 'progressive': 3, 'fixed': 2 },
        r4overfit: { 'gsr_arousal': 5, 'eeg_aai': 4, 'eye_fixation': 4, 'iat_association': 3, 'survey_data': 2 }
    };

    var FEEDBACK = {
        r1: {
            'C-3': 'Excellent choice. C-3 has the strongest combined approach motivation (AAI +0.48) and high engagement (EI 71), with survey-neuro alignment confirming robust signal quality.',
            'C-1': 'Good choice for System 2-dominant contexts. High engagement (EI 78) is appropriate for high-dwell digital environments, though lower approach motivation limits broad use.',
            'C-5': 'Partially defensible. Strong AAI (+0.38) is genuine, but very high GSR (81) with ambiguous valence and 15-second format limits utility as primary creative without deeper valence confirmation.',
            'C-4': 'Moderate choice. High EI (83) may indicate information processing rather than approach motivation. The moderate AAI (+0.22) suggests limited emotional resonance.',
            'C-2': 'Common error. High survey score (7.8) masks a negative AAI (-0.12). GSR arousal (71) without approach motivation suggests the ad triggers attention without positive engagement. Survey respondents reported deliberate evaluation, not automatic approach response.'
        },
        r2: {
            'P-6': 'Excellent. Maximum loss aversion suppression (lowest GSR at price reveal), strongest implicit value associations, and highest WTP uplift (+24%). The premium reference anchor restructures the comparative context before price is revealed.',
            'P-4': 'Strong choice. Operationalizes the default effect directly. Low arousal indicates reduced loss aversion. Particularly effective for DTC channel.',
            'P-3': 'Good choice. High benefit salience engages System 2 evaluation. Strong positive implicit associations, though claims may feel overclaimed to skeptical segments.',
            'P-8': 'Reasonable. Loss aversion toward running out is well-directed, but cognitive arithmetic may slow conversion at point of sale.',
            'P-5': 'Moderate. Social proof activates self-concept congruence but may dilute the exclusivity that premium brand consumers seek.',
            'P-2': 'Moderate. Downward anchor is effective but the coffee norm comparison is challenged when MERIDIAN targets a premium segment that may not see coffee as a relevant reference.',
            'P-9': 'Below average. Values alignment is positive but may reduce perceived performance credibility for a functional beverage.',
            'P-7': 'Poor choice. IAT data shows premium brand consumers have negative implicit associations between scarcity messaging and brand trustworthiness. High GSR reflects activated skepticism, not purchase motivation.',
            'P-1': 'Weakest option. Maximum loss aversion activation with zero mitigation mechanism. Bare price presentation generates the strongest negative arousal at reveal.'
        },
        r3ethics: {
            'principled': 'Full compliance. Your response distinguishes between techniques retained and modified, grounded in the autonomy/transparency/benefit alignment framework.',
            'generic': 'Partial credit. You acknowledged ethical dimensions but did not connect principles to your specific decisions.',
            'commercial': 'Non-compliance. A purely commercial defense does not engage with autonomy or transparency dimensions.'
        }
    };

    class MindMarketAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'MindMarket: Neuromarketing & Decision Neuroscience';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    dqsTotal: 0,
                    calibrationTotal: 0,
                    ethicsScore: 0,
                    overFitScore: 0,
                    launchSuccess: 0,
                    roundScores: [],
                    calibrationScores: [],
                    dqsHistory: [],
                    totalHistory: [],
                    confidenceHistory: [],
                    qualityHistory: [],
                    ethicsSubmitted: false,
                    randomEventApplied: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    mainChoice: '',
                    secondChoice: '',
                    ethicsChoice: '',
                    overfitChoice: '',
                    confidence: 'medium'
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, ROUNDS.length - 1);
            var round = ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var dataEl = document.getElementById('dataContent');
            var dynEl = document.getElementById('dynamicControls');

            if (titleEl) titleEl.textContent = round.title;
            if (textEl) textEl.innerHTML = round.briefing;
            if (dataEl) dataEl.innerHTML = round.dataHtml;

            if (!dynEl) return;

            var period = state.currentPeriod || 1;
            var html = '';

            if (period === 1) {
                html += '<label for="mainChoiceInput" data-i18n="r1_creative_label">Primary Creative Selection</label>';
                html += '<select id="mainChoiceInput" class="form-control">';
                html += '<option value="">-- Select Creative --</option>';
                html += '<option value="C-1">C-1: The Science of You</option>';
                html += '<option value="C-2">C-2: Morning. Owned.</option>';
                html += '<option value="C-3">C-3: Clean Inside Out</option>';
                html += '<option value="C-4">C-4: Athletes and Others</option>';
                html += '<option value="C-5">C-5: MERIDIAN: The Edge</option>';
                html += '</select>';
            } else if (period === 2) {
                html += '<label for="mainChoiceInput" data-i18n="r2_frame_label">Pricing Frame Selection</label>';
                html += '<select id="mainChoiceInput" class="form-control">';
                html += '<option value="">-- Select Pricing Frame --</option>';
                html += '<option value="P-1">P-1: Bare Price</option>';
                html += '<option value="P-2">P-2: Per-Day Anchor</option>';
                html += '<option value="P-3">P-3: Cost-Per-Benefit</option>';
                html += '<option value="P-4">P-4: Subscription Default</option>';
                html += '<option value="P-5">P-5: Social Proof Price</option>';
                html += '<option value="P-6">P-6: Premium Reference Anchor</option>';
                html += '<option value="P-7">P-7: Scarcity Frame</option>';
                html += '<option value="P-8">P-8: Bundle Frame</option>';
                html += '<option value="P-9">P-9: Charitable Giving Embed</option>';
                html += '</select>';
            } else if (period === 3) {
                html += '<label for="mainChoiceInput" data-i18n="r3_shelf_label">Shelf Configuration</label>';
                html += '<select id="mainChoiceInput" class="form-control">';
                html += '<option value="">-- Select Configuration --</option>';
                html += '<option value="A">Shelf A: Price-first fixation, linear gaze</option>';
                html += '<option value="B">Shelf B: Brand-first fixation, moderate complexity</option>';
                html += '<option value="C">Shelf C: Ingredient-first, high backtracking</option>';
                html += '</select>';

                html += '<label for="secondChoiceInput" data-i18n="r3_ux_label">Digital UX Variant</label>';
                html += '<select id="secondChoiceInput" class="form-control">';
                html += '<option value="">-- Select UX Variant --</option>';
                html += '<option value="V-1">V-1: High density, social proof above fold</option>';
                html += '<option value="V-2">V-2: Low density, social proof above fold</option>';
                html += '<option value="V-3">V-3: High density, social proof below fold</option>';
                html += '<option value="V-4">V-4: Low density, social proof below fold</option>';
                html += '</select>';

                html += '<label for="ethicsChoiceInput" data-i18n="r3_ethics_label">Ethical Checkpoint Response</label>';
                html += '<select id="ethicsChoiceInput" class="form-control">';
                html += '<option value="">-- Select Ethical Approach --</option>';
                html += '<option value="principled">Principled Defense: Distinguish retained vs. rejected techniques using autonomy/transparency framework</option>';
                html += '<option value="generic">Generic Acknowledgment: Acknowledge ethical dimensions without connecting to specific decisions</option>';
                html += '<option value="commercial">Commercial Defense: Defend all choices on commercial grounds without ethical engagement</option>';
                html += '</select>';
            } else if (period === 4) {
                html += '<label for="mainChoiceInput" data-i18n="r4_schedule_label">Reward Schedule Architecture</label>';
