        getPerformanceSummary(history) {
            if (!history || history.length === 0) return {};

            var last = history[history.length - 1];
            var ds = window.mySimulation.state.domainState;
            var totalScore = ds.totalScore;
            var lss = ds.launchSuccess;

            var performance = 'Developing';
            if (lss >= 80) performance = 'Excellent';
            else if (lss >= 60) performance = 'Good';
            else if (lss >= 40) performance = 'Moderate';

            var insights = [];
            if (lss >= 75) {
                insights.push('Strong neuromarketing literacy demonstrated. You correctly decoded neural signals while respecting interpretive limits.');
            }
            if (ds.ethicsScore === 2) {
                insights.push('Full ethical compliance achieved. Your principled defense distinguished between legitimate persuasion and manipulation.');
            } else if (ds.ethicsScore < 2) {
                insights.push('Ethics gap identified. A more nuanced engagement with autonomy, transparency, and benefit alignment would strengthen your framework.');
            }

            var calTotal = ds.calibrationScores.reduce(function(a, b) { return a + b; }, 0);
            if (calTotal > 4) {
                insights.push('Excellent confidence calibration. Your uncertainty matched the quality of your decisions.');
            } else if (calTotal < 0) {
                insights.push('Over-confidence detected. Several high-confidence calls on ambiguous signals resulted in calibration penalties.');
            }

            if (ds.overFitScore >= 4) {
                insights.push('Strong self-critical reasoning in the anti-over-fit defense. Recognizing your own interpretive vulnerabilities is the highest-order skill in data-driven decision-making.');
            }

            return {
                totalScore: Math.round(totalScore),
                launchSuccess: lss,
                performance: performance,
                insights: insights,
                ethicsScore: ds.ethicsScore + '/2',
                overFitDefense: ds.overFitScore + '/5'
            };
        }

